import AVFoundation
func t(_ name: String, _ f: () throws -> Void) { do { try f(); print("OK  ", name) } catch { print("FAIL", name, error.localizedDescription) } }
let mono = AVAudioFormat(standardFormatWithSampleRate: 44100, channels: 1)!
t("vp + tap + player(nil)") { let e = AVAudioEngine(); try e.inputNode.setVoiceProcessingEnabled(true); e.inputNode.installTap(onBus: 0, bufferSize: 1024, format: nil) { _, _ in }; let p = AVAudioPlayerNode(); e.attach(p); e.connect(p, to: e.mainMixerNode, format: nil); try e.start(); print("   player fmt", p.outputFormat(forBus: 0)); e.stop() }
t("vp + tap + player(44.1 mono)") { let e = AVAudioEngine(); try e.inputNode.setVoiceProcessingEnabled(true); e.inputNode.installTap(onBus: 0, bufferSize: 1024, format: nil) { _, _ in }; let p = AVAudioPlayerNode(); e.attach(p); e.connect(p, to: e.mainMixerNode, format: mono); try e.start(); e.stop() }
t("vp + player first, then tap") { let e = AVAudioEngine(); try e.inputNode.setVoiceProcessingEnabled(true); let p = AVAudioPlayerNode(); e.attach(p); e.connect(p, to: e.mainMixerNode, format: mono); e.inputNode.installTap(onBus: 0, bufferSize: 1024, format: nil) { _, _ in }; try e.start(); e.stop() }
t("vp + tap + prepare + player") { let e = AVAudioEngine(); try e.inputNode.setVoiceProcessingEnabled(true); e.inputNode.installTap(onBus: 0, bufferSize: 1024, format: nil) { _, _ in }; let p = AVAudioPlayerNode(); e.attach(p); e.connect(p, to: e.mainMixerNode, format: mono); e.prepare(); try e.start(); e.stop() }
t("vp + mono tap + player") { let e = AVAudioEngine(); try e.inputNode.setVoiceProcessingEnabled(true); let f = e.inputNode.outputFormat(forBus: 0); let m = AVAudioFormat(commonFormat: .pcmFormatFloat32, sampleRate: f.sampleRate, channels: 1, interleaved: false); e.inputNode.installTap(onBus: 0, bufferSize: 1024, format: m) { _, _ in }; let p = AVAudioPlayerNode(); e.attach(p); e.connect(p, to: e.mainMixerNode, format: mono); try e.start(); e.stop() }
t("vp + ducking config + tap + player") { let e = AVAudioEngine(); try e.inputNode.setVoiceProcessingEnabled(true); if #available(macOS 14.0, *) { e.inputNode.voiceProcessingOtherAudioDuckingConfiguration = AVAudioVoiceProcessingOtherAudioDuckingConfiguration(enableAdvancedDucking: false, duckingLevel: .min) }; e.inputNode.installTap(onBus: 0, bufferSize: 1024, format: nil) { _, _ in }; let p = AVAudioPlayerNode(); e.attach(p); e.connect(p, to: e.mainMixerNode, format: mono); try e.start(); e.stop() }
